import{_ as e,o as a,c as s,ae as n}from"./chunks/framework.EHGTsUvI.js";const c=JSON.parse('{"title":"Season 2","description":"","frontmatter":{"title":"Season 2"},"headers":[],"relativePath":"Main/Main/Company/Seasons/season2.md","filePath":"Main/Main/Company/Seasons/season2.md"}'),o={name:"Main/Main/Company/Seasons/season2.md"};function r(i,t,d,l,p,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="company-season-2" tabindex="-1">Company Season 2 <a class="header-anchor" href="#company-season-2" aria-label="Permalink to &quot;Company Season 2&quot;">​</a></h1><p><strong>Season 2</strong> was the second Season of the <strong>Companies</strong> system in Farming And Friends.</p><p>Season 2 introduced new limited equipment that could be obtained as part of the Company progression system.</p><h2 id="season-overview" tabindex="-1">Season Overview <a class="header-anchor" href="#season-overview" aria-label="Permalink to &quot;Season Overview&quot;">​</a></h2><p>Season 2 expanded the selection of Company-exclusive equipment with new machinery designed for large-scale farming.</p><p>The documented Season 2 equipment includes:</p><ul><li><strong>ML10</strong> — Level 5 Harvester</li><li><strong>CW26</strong> — Level 5 Sprinkler</li></ul><p>Both pieces of equipment provide a <strong>4-tile working width</strong>, making them useful for large-scale farming.</p><h2 id="season-2-equipment" tabindex="-1">Season 2 Equipment <a class="header-anchor" href="#season-2-equipment" aria-label="Permalink to &quot;Season 2 Equipment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Equipment</th><th>Type</th><th>Level</th><th>Working Width</th><th>Capacity</th></tr></thead><tbody><tr><td>ML10</td><td>Harvester</td><td>Level 5</td><td>4 Tiles</td><td>600–1,100</td></tr><tr><td>CW26</td><td>Sprinkler</td><td>Level 5</td><td>4 Tiles</td><td>N/A</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Both pieces of equipment are associated with Season 2 of Companies. Availability may change after the Season ends.</p></blockquote><hr><h2 id="ml10" tabindex="-1">ML10 <a class="header-anchor" href="#ml10" aria-label="Permalink to &quot;ML10&quot;">​</a></h2><p>The <strong>ML10</strong> is a Level 5 crop harvester introduced during Season 2 of Companies.</p><h3 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h3><p>The ML10 is used to <strong>harvest crops</strong>.</p><p>It can harvest <strong>4 tiles at once</strong>, allowing large areas of farmland to be harvested more quickly than smaller harvesters.</p><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Equipment</td><td>ML10</td></tr><tr><td>Type</td><td>Harvester</td></tr><tr><td>Level</td><td>Level 5</td></tr><tr><td>Working Width</td><td>4 Tiles</td></tr><tr><td>Speed</td><td>36/51</td></tr><tr><td>Capacity</td><td>600–1,100</td></tr><tr><td>Availability</td><td>Limited</td></tr><tr><td>Season</td><td>Season 2</td></tr></tbody></table><h3 id="useful-information" tabindex="-1">Useful Information <a class="header-anchor" href="#useful-information" aria-label="Permalink to &quot;Useful Information&quot;">​</a></h3><ul><li>The ML10 is a <strong>Level 5</strong> harvester.</li><li>It harvests <strong>4 tiles</strong> at a time.</li><li>It has a crop capacity of <strong>600–1,100</strong>.</li><li>Its listed speed is <strong>36/51</strong>.</li><li>It was introduced as limited equipment during <strong>Season 2 of Companies</strong>.</li><li>It is designed for large-scale harvesting.</li></ul><hr><h2 id="cw26" tabindex="-1">CW26 <a class="header-anchor" href="#cw26" aria-label="Permalink to &quot;CW26&quot;">​</a></h2><p>The <strong>CW26</strong> is a Level 5 sprinkler introduced during Season 2 of Companies.</p><h3 id="what-it-does-1" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does-1" aria-label="Permalink to &quot;What It Does&quot;">​</a></h3><p>The CW26 is used to <strong>water crops</strong>.</p><p>It has a working width of <strong>4 tiles</strong>, allowing players to water a larger area of farmland at once.</p><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Equipment</td><td>CW26</td></tr><tr><td>Type</td><td>Sprinkler</td></tr><tr><td>Level</td><td>Level 5</td></tr><tr><td>Working Width</td><td>4 Tiles</td></tr><tr><td>Availability</td><td>Limited</td></tr><tr><td>Season</td><td>Season 2</td></tr></tbody></table><h3 id="useful-information-1" tabindex="-1">Useful Information <a class="header-anchor" href="#useful-information-1" aria-label="Permalink to &quot;Useful Information&quot;">​</a></h3><ul><li>The CW26 is a <strong>Level 5</strong> sprinkler.</li><li>It covers <strong>4 tiles</strong> at a time.</li><li>It was available during <strong>Season 2 of Companies</strong>.</li><li>Its wide working area makes it useful for large-scale farming.</li><li>It is part of the limited Company equipment associated with Season 2.</li></ul><hr><h2 id="season-2-equipment-progression" tabindex="-1">Season 2 Equipment Progression <a class="header-anchor" href="#season-2-equipment-progression" aria-label="Permalink to &quot;Season 2 Equipment Progression&quot;">​</a></h2><p>The Season 2 equipment covers two important areas of farming:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CW26</span></span>
<span class="line"><span>Watering</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Crops</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>ML10</span></span>
<span class="line"><span>Harvesting</span></span></code></pre></div>`,33)])])}const u=e(o,[["render",r]]);export{c as __pageData,u as default};
